SELECT id, symbol, interval_code, decision, candle_open_time, generated_at, created_at, latest_price FROM crypto_ai.trade_signal WHERE id IN (156850,156852,156853,159487,166819,168277,172587,176927) ORDER BY symbol, generated_at;
SELECT id, symbol, interval_code, decision, candle_open_time, generated_at, created_at FROM crypto_ai.trade_signal WHERE ((symbol='EGLDUSDT' AND generated_at BETWEEN '2026-10-11 21:00:00' AND '2026-10-11 21:00:12') OR (symbol='DOGEUSDT' AND generated_at BETWEEN '2026-10-12 04:26:00' AND '2026-10-12 04:26:06') OR (symbol='SHIBUSDT' AND generated_at BETWEEN '2026-10-12 07:15:00' AND '2026-10-12 07:15:45')) ORDER BY symbol, generated_at LIMIT 50;